function tocaCesta(o) {
  return o.y + o.r >= cesta.y &&
         o.y - o.r <= cesta.y + cesta.alto &&
         Math.abs(o.x - cesta.x) <= cesta.ancho / 2 + o.r * 0.5;
}

function dificultad() {
  return {
    velocidad: Math.min(2.4, 1 + 0.15 * (nivel - 1)),
    intervalo: Math.max(0.32, 0.85 / (1 + 0.18 * (nivel - 1))),
    piedras: Math.min(0.45, 0.22 + 0.03 * (nivel - 1))
  };
}
